import React, { useState, ChangeEvent, FormEvent, useEffect } from "react";
import axios from "axios";
import { useNavigate, useParams, Link } from "react-router-dom";
import Loading from "../Components/Loading";
import ItemSelect from "../Components/ItemSelect";
import styles from "../styles/InquirPage/InquirUpdate.module.css";

interface Inquir {
  employee_no2: number;
  name: string;
  content_choice: string;
  inquiry: string;
  answer: string;
}

interface Member {
  employee_no: number;
  name: string;
  shop: string;
  authority: boolean;
  administrator: boolean;
}

interface Response {
  inquir_data: Inquir;
  login_data: Member;
  inquir_member_data: Member;
}

const InquirUpdate: React.FC = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState<Inquir | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const { id } = useParams<{ id: string }>();
  const [memberData, setMemberData] = useState<Member | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get<Response>(`${process.env.REACT_APP_API_BASE_URL}/api/inquir_update/${id}/`, { withCredentials: true });
        const { inquir_data, login_data } = response.data;
        setFormData(inquir_data);
        setMemberData(login_data);
      } catch (err) {
        if (axios.isAxiosError(err)) {
          if (err.response?.status === 401) navigate("/login");
          else if (err.response?.status === 403) navigate("/");
          else setError(err.response?.data.message);
        } else setError("不明なエラーが発生しました。IT担当者に連絡してください。");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id, navigate]);

  const handleChange = (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = event.target;
    setFormData((prevData) => {
      if (!prevData) return null;
      return {
        ...prevData,
        [name]: value,
      } as Inquir;
    });
  };

  const handleContentChange = (event: ChangeEvent<HTMLSelectElement>) => {
    const value = event.target.value;
    setFormData((prevData) => {
      if (!prevData) return null;
      return {
        ...prevData,
        content_choice: value,
      } as Inquir;
    });
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);

    if (!formData) return;

    try {
      await axios.put(`${process.env.REACT_APP_API_BASE_URL}/api/inquir_update/${id}/`, formData, { withCredentials: true });
      alert("登録完了！");
      navigate("/inquir-list");
    } catch (err) {
      if (axios.isAxiosError(err)) {
        if (err.response?.status === 401) navigate("/login");
        else if (err.response?.status === 403) navigate("/");
        else setError(err.response?.data.message);
      } else setError("不明なエラーが発生しました。IT担当者に連絡してください。");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    const confirmed = window.confirm("削除すると戻せません。削除しますか？");
    if (!confirmed) return;

    try {
      await axios.delete(`${process.env.REACT_APP_API_BASE_URL}/api/inquir_update/${id}/`, { withCredentials: true });
      alert("削除が完了しました");
      navigate("/inquir-list");
    } catch (err) {
      if (axios.isAxiosError(err)) {
        if (err.response?.status === 401) navigate("/login");
        else if (err.response?.status === 403) navigate("/");
        else setError(err.response?.data.message);
      } else setError("不明なエラーが発生しました。IT担当者に連絡してください。");
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div><Loading isLoading={loading} /></div>;
  if (error) return <div>Error: {error}</div>;
  if (!formData) return <div>データが見つかりません</div>;

  return (
    <>
      <Loading isLoading={loading} />
      <div className={styles["inquir-update-wrapper"]}>
        <h1 className={styles["h1-collar"]}>問い合わせ編集</h1>
        <nav className={styles["inquir-nav"]}>
          <Link to="/inquir-list">問い合わせ履歴</Link>
        </nav>

        <form
          onSubmit={handleSubmit}
          onKeyDown={(e) => {
            if (e.key === "Enter" && e.target instanceof HTMLInputElement && e.target.type !== "textarea") {
              e.preventDefault();
              (e.target as HTMLInputElement).blur();
            }
          }}
        >
          <div className={styles["search-bar"]}>
            <label htmlFor="ItemSelect">内容選択:</label>
            <ItemSelect
              id="ItemSelect"
              name="content_choice"
              value={formData.content_choice}
              onChange={handleContentChange}
            />
            <label htmlFor="inquiry">問い合わせ：</label>
            <textarea
              id="inquiry"
              name="inquiry"
              value={formData.inquiry}
              onChange={handleChange}
              rows={5}
            />
            {memberData?.administrator && (
              <>
                <label htmlFor="answer">回答：</label>
                <textarea
                  id="answer"
                  name="answer"
                  value={formData.answer}
                  onChange={handleChange}
                  rows={5}
                />
              </>
            )}
            <div className={styles["pagination-buttons"]}>
              <button type="submit" className="pink_button">編集</button>
              <button type="button" onClick={handleDelete} className="pink_button">削除</button>
            </div>
          </div>
        </form>
      </div>
    </>
  );
};

export default InquirUpdate;